1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body { margin: 0; font: 16px/1.4 system-ui, sans-serif; background: #f6f6f4; color: #222; }
10	  main { max-width: 520px; margin: 40px auto; padding: 0 16px; }
11	  h1 { font-size: 1.6rem; margin: 0 0 16px; }
12	  form { display: flex; gap: 8px; margin-bottom: 16px; }
13	  input { flex: 1; padding: 10px; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
14	  button { padding: 10px 14px; font: inherit; border: 0; border-radius: 6px; background: #2b6cb0; color: #fff; cursor: pointer; }
15	  ul { list-style: none; margin: 0; padding: 0; }
16	  li { display: flex; align-items: center; gap: 8px; padding: 10px 12px; background: #fff; border: 1px solid #e3e3e3; border-radius: 6px; margin-bottom: 8px; }
17	  li span { flex: 1; word-break: break-word; }
18	  li button { background: #c53030; padding: 6px 10px; font-size: 0.9rem; }
19	</style>
20	</head>
21	<body>
22	<main>
23	  <h1>Todos</h1>
24	  <form id="todo-form">
25	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
26	    <button data-testid="todo-add" type="submit">Add</button>
27	  </form>
28	  <ul data-testid="todo-list"></ul>
29	</main>
30	<script>
31	  var STORAGE_KEY = 'todos';
32	  var form = document.getElementById('todo-form');
33	  var input = document.querySelector('[data-testid="todo-input"]');
34	  var list = document.querySelector('[data-testid="todo-list"]');
35	  var todos = loadTodos();
36	
37	  // [REQ-001]
38	  function loadTodos() {
39	    try {
40	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
41	      return Array.isArray(data) ? data : [];
42	    } catch (e) {
43	      return [];
44	    }
45	  }
46	
47	  // [REQ-001]
48	  function saveTodos() {
49	    try {
50	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
51	    } catch (e) {}
52	  }
53	
54	  // [REQ-001]
55	  function makeId() {
56	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
57	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
58	  }
59	
60	  // [REQ-001]
61	  function addTodo(text) {
62	    text = text.trim();
63	    if (!text) return;
64	    todos.push({ id: makeId(), text: text, createdAt: Date.now() });
65	    saveTodos();
66	    render();
67	  }
68	
69	  // [REQ-001]
70	  function deleteTodo(id) {
71	    todos = todos.filter(function (t) { return t.id !== id; });
72	    saveTodos();
73	    render();
74	  }
75	
76	  // [REQ-001]
77	  function render() {
78	    list.textContent = '';
79	    todos.forEach(function (todo) {
80	      var li = document.createElement('li');
81	      li.setAttribute('data-testid', 'todo-item');
82	      li.dataset.id = todo.id;
83	
84	      var span = document.createElement('span');
85	      span.setAttribute('data-testid', 'todo-text');
86	      span.textContent = todo.text;
87	
88	      var del = document.createElement('button');
89	      del.type = 'button';
90	      del.setAttribute('data-testid', 'todo-delete');
91	      del.textContent = 'Delete';
92	      del.addEventListener('click', function () { deleteTodo(todo.id); });
93	
94	      li.appendChild(span);
95	      li.appendChild(del);
96	      list.appendChild(li);
97	    });
98	  }
99	
100	  form.addEventListener('submit', function (e) {
101	    e.preventDefault();
102	    addTodo(input.value);
103	    input.value = '';
104	    input.focus();
105	  });
106	
107	  render();
108	</script>
109	</body>
110	</html>
